CREATE TYPE "BrainSourceType" AS ENUM ('HUMAN','THREAD','TASK','HERMES','MNEMOSYNE','FILE','INTEGRATION','SYSTEM'); CREATE TYPE "BrainRecordStatus" AS ENUM ('ACTIVE','ARCHIVED'); CREATE TYPE "MemoryType" AS ENUM ('FACT','PREFERENCE','LESSON','EXPERIENCE','ENTITY','OBSERVATION');
CREATE TABLE "KnowledgeSource" ("id" TEXT NOT NULL,"projectId" TEXT NOT NULL,"type" "BrainSourceType" NOT NULL,"label" TEXT NOT NULL,"reference" TEXT,"occurredAt" TIMESTAMP(3),"createdById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "KnowledgeSource_pkey" PRIMARY KEY("id"));
CREATE TABLE "ProjectConstitution" ("id" TEXT NOT NULL,"projectId" TEXT NOT NULL,"title" TEXT NOT NULL DEFAULT 'Project Constitution',"content" TEXT NOT NULL,"status" "BrainRecordStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ProjectConstitution_pkey" PRIMARY KEY("id"));
CREATE TABLE "KnowledgeItem" ("id" TEXT NOT NULL,"projectId" TEXT NOT NULL,"sourceId" TEXT,"title" TEXT NOT NULL,"content" TEXT NOT NULL,"category" TEXT NOT NULL DEFAULT 'GENERAL',"status" "BrainRecordStatus" NOT NULL DEFAULT 'ACTIVE',"createdById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "KnowledgeItem_pkey" PRIMARY KEY("id"));
CREATE TABLE "Decision" ("id" TEXT NOT NULL,"projectId" TEXT NOT NULL,"sourceId" TEXT,"title" TEXT NOT NULL,"decision" TEXT NOT NULL,"rationale" TEXT,"status" "BrainRecordStatus" NOT NULL DEFAULT 'ACTIVE',"decidedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"decidedById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Decision_pkey" PRIMARY KEY("id"));
CREATE TABLE "ProjectMemory" ("id" TEXT NOT NULL,"projectId" TEXT NOT NULL,"sourceId" TEXT,"title" TEXT NOT NULL,"content" TEXT NOT NULL,"type" "MemoryType" NOT NULL DEFAULT 'FACT',"confidence" TEXT,"importance" INTEGER NOT NULL DEFAULT 3,"status" "BrainRecordStatus" NOT NULL DEFAULT 'ACTIVE',"learnedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ProjectMemory_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "KnowledgeSource_id_projectId_key" ON "KnowledgeSource"("id","projectId"); CREATE UNIQUE INDEX "ProjectConstitution_projectId_key" ON "ProjectConstitution"("projectId"); CREATE INDEX "KnowledgeItem_projectId_status_updatedAt_idx" ON "KnowledgeItem"("projectId","status","updatedAt"); CREATE INDEX "Decision_projectId_status_decidedAt_idx" ON "Decision"("projectId","status","decidedAt"); CREATE INDEX "ProjectMemory_projectId_type_status_updatedAt_idx" ON "ProjectMemory"("projectId","type","status","updatedAt");
ALTER TABLE "KnowledgeSource" ADD FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE; ALTER TABLE "ProjectConstitution" ADD FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE; ALTER TABLE "KnowledgeItem" ADD FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE; ALTER TABLE "KnowledgeItem" ADD FOREIGN KEY ("sourceId","projectId") REFERENCES "KnowledgeSource"("id","projectId") ON DELETE RESTRICT; ALTER TABLE "Decision" ADD FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE; ALTER TABLE "Decision" ADD FOREIGN KEY ("sourceId","projectId") REFERENCES "KnowledgeSource"("id","projectId") ON DELETE RESTRICT; ALTER TABLE "ProjectMemory" ADD FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE; ALTER TABLE "ProjectMemory" ADD FOREIGN KEY ("sourceId","projectId") REFERENCES "KnowledgeSource"("id","projectId") ON DELETE RESTRICT;
